    @Test
    public void testDeregister() {
        ZapposJson zapposJson = new ZapposJson();
        JsonBeanIntrospector beanIntrospector = new JsonBeanIntrospector();
        JsonReaderCodeGenerator generator = new JsonReaderCodeGenerator(zapposJson, beanIntrospector);

        // Use reflection to access and modify the JSON_READER_INVOKERS map
        try {
            java.lang.reflect.Field field = JsonReaderCodeGenerator.class.getDeclaredField("JSON_READER_INVOKERS");
            field.setAccessible(true);
            @SuppressWarnings("unchecked")
            Map<Class<?>, JsonReaderInvoker> jsonReaderInvokers = (Map<Class<?>, JsonReaderInvoker>) field.get(generator);

            // Test with a class that is not registered
            Class<?> clazz1 = String.class;
            generator.deregister(clazz1);
            assertNull(jsonReaderInvokers.get(clazz1));

            // Test with a class that is registered
            Class<?> clazz2 = Integer.class;
            JsonReaderInvoker invoker = obj -> null; // Dummy invoker
            jsonReaderInvokers.put(clazz2, invoker);

            generator.deregister(clazz2);
            assertNull(jsonReaderInvokers.get(clazz2));

            //Test with a class that is registered, deregister multiple times.
            Class<?> clazz3 = Long.class;
            JsonReaderInvoker invoker2 = obj -> null; // Dummy invoker
            jsonReaderInvokers.put(clazz3, invoker2);
            assertSame(invoker2, jsonReaderInvokers.get(clazz3));
            generator.deregister(clazz3);
            assertNull(jsonReaderInvokers.get(clazz3));
            generator.deregister(clazz3); // deregistering a second time should not cause any issues.
            assertNull(jsonReaderInvokers.get(clazz3));

        } catch (NoSuchFieldException | IllegalAccessException e) {
            throw new RuntimeException(e);
        }
    }
